import numpy as np


def compute_max_radii(centers):
    """Iterative equalization radius solver."""
    n = centers.shape[0]
    radii = np.array([min(x, y, 1 - x, 1 - y) for (x, y) in centers])

    for _ in range(80):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = float(np.sqrt(np.sum((centers[i] - centers[j]) ** 2)))
                s = radii[i] + radii[j]
                if s > d + 1e-12:
                    excess = (s - d) / 2.0
                    radii[i] = max(radii[i] - excess, 0.0)
                    radii[j] = max(radii[j] - excess, 0.0)
                    changed = True
        for i in range(n):
            x, y = centers[i]
            cap = min(x, y, 1 - x, 1 - y)
            if radii[i] > cap:
                radii[i] = cap
                changed = True
        if not changed:
            break

    return radii


